patch:
diff --git a/repro/no-useless-assignment-try-catch.js b/repro/no-useless-assignment-try-catch.js
new file mode 100644
index 0000000..a5daf70
--- /dev/null
+++ b/repro/no-useless-assignment-try-catch.js
@@ -0,0 +1,54 @@
+"use strict";
+// Repro: no-useless-assignment false positive when a try block ends with return/break
+// and the assigned value is read in the catch block.
+const { Linter } = require("../lib/api");
+const linter = new Linter({ configType: "flat" });
+const config = [{ rules: { "no-useless-assignment": "error" } }];
+
+const cases = {
+    "report (try ends with return) - BUG": `
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+function unsafeFn() { throw new Error(); }`,
+    "try ends with break - BUG": `
+function fn() {
+  let v;
+  for (;;) {
+    try {
+      v = 42;
+      unsafeFn();
+      break;
+    } catch {
+      return v;
+    }
+  }
+}`,
+    "control: no return in try - OK": `
+function fn() {
+  let v;
+  try {
+    v = 42;
+    unsafeFn();
+  } catch {
+    return v;
+  }
+}`
+};
+
+let bugs = 0;
+for (const [name, code] of Object.entries(cases)) {
+    const msgs = linter.verify(code, config, "x.js");
+    console.log(`--- ${name}: ${msgs.length} message(s)`);
+    for (const m of msgs) console.log(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+    if (name.includes("BUG") && msgs.length) bugs++;
+}
+console.log(bugs ? `\nBUG REPRODUCED in ${bugs} case(s)` : "\nnot reproduced");
+process.exitCode = bugs ? 1 : 0;
